# Try minimum and maximum values in blocks

def min_val_block(grid):
    result = []
    for i in range(3):
        row = []
        for j in range(3):
            block = [grid[i*3+r][j*3+c] for r in range(3) for c in range(3)]
            row.append(min(block))
        result.append(row)
    return result

def max_val_block(grid):
    result = []
    for i in range(3, 6):
        row = []
        for j in range(3):
            block = [grid[i*3+r][j*3+c] for r in range(3) for c in range(3)]
            row.append(max(block))
        result.append(row)
    return result

def only_non_5(grid):
    result = []
    for i in range(3):
        row = []
        for j in range(3):
            block = [grid[i*3+r][j*3+c] for r in range(3) for c in range(3)]
            non_5 = [v for v in block if v != 5]
            if non_5:
                if len(non_5) == 1:
                    row.append(non_5[0])
                else:
                    # Maybe min or max?
                    row.append(min(non_5))
            else:
                row.append(0)
        result.append(row)
    return result

